          int xloc = label - yloc * TILE_COLS;

          xloc += blockIdx.x * TILE_COLS;
          yloc += blockIdx.y * TILE_ROWS;

          label = yloc * edges.cols + xloc;

          comps.ptr(y + CTA_SIZE_Y*i)[x + CTA_SIZE_X*j] = label;
        }
      }    
    }
